WITH candidates AS (SELECT DISTINCT ON (l.id) l.id AS level_id,l.xx_hash,coalesce(i.name,v.payload->>'name') AS name,s.authors AS author_ids,ARRAY(SELECT coalesce(author_user.steam_name,author.id) FROM unnest(s.authors) WITH ORDINALITY author(id,n) LEFT JOIN public."user" author_user ON author_user.steam_id::text=author.id ORDER BY author.n) AS author_names,coalesce(nullif(i.image_url,''),nullif(other_image.image_url,''),nullif(wi.image_url,'')) AS image_url {{candidates_from_sql}} ORDER BY l.id,s.workshop_id,e.position), eligible_votes AS (SELECT v.id_level,v.vote_type,v.id_user FROM zc_private.level_submission_vote v JOIN candidates c ON c.level_id=v.id_level WHERE v.id_contest=$1 AND v.vote_type=ANY($2)), tallies AS (SELECT id_level,vote_type,count(*) AS votes FROM eligible_votes GROUP BY id_level,vote_type), voters AS (SELECT vote_type,count(DISTINCT id_user) AS unique_voters FROM eligible_votes GROUP BY vote_type) SELECT c.*,t.vote_type,coalesce(v.votes,0)::bigint AS votes, coalesce(p.unique_voters,0)::bigint AS unique_voters FROM candidates c CROSS JOIN unnest($2::smallint[]) t(vote_type) LEFT JOIN tallies v ON v.id_level=c.level_id AND v.vote_type=t.vote_type LEFT JOIN voters p ON p.vote_type=t.vote_type ORDER BY t.vote_type,votes DESC,coalesce(c.name,c.xx_hash) COLLATE "C",c.level_id
